head.script:
scwin.setDataList1 = function() {
    var data = [{
        "value": "a1",
        "label": "a1",
        "depth": "1"
    }, {
        "value": "a1-1",
        "label": "a1-1",
        "depth": "2"
    }, {
        "value": "a1-1-1",
        "label": "a1-1-1",
        "depth": "3"
    }, {
        "value": "a1-1-2",
        "label": "a1-1-2",
        "depth": "3"
    }, {
        "value": "a1-1-2-1",
        "label": "a1-1-2-1",
        "depth": "4"
    }, {
        "value": "a1-1-3",
        "label": "a1-1-3",
        "depth": "3"
    }, {
        "value": "a1-2",
        "label": "a1-2",
        "depth": "2"
    }, {
        "value": "a1-2-1",
        "label": "a1-2-1",
        "depth": "3"
    }, {
        "value": "a1-2-1-1",
        "label": "a1-2-1-1",
        "depth": "4"
    }, {
        "value": "a2",
        "label": "a2",
        "depth": "1"
    }, {
        "value": "a2-1",
        "label": "a2-1",
        "depth": "2"
    }, {
        "value": "a2-1-1",
        "label": "a2-1-1",
        "depth": "3"
    }, {
        "value": "a3",
        "label": "a3",
        "depth": "1"
    }, {
        "value": "a3-1",
        "label": "a3-1",
        "depth": "2"
    }];
    dataList1.setJSON(data);
};
scwin.trigger1_onclick = function(e) {
    treeview1.checkByValue("a1-1-2", true, true);
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.setDataList1();
    setTimeout(function() {
        window.ntime = performance.timing;
        window.total = ntime.loadEventEnd - ntime.navigationStart; //전체 소요시간
        window.redirect = ntime.redirectEnd - ntime.redirectStart; // 동일 origin에서의 redirect 시간
        window.cache = ntime.domainLookupStart - ntime.fetchStart; // cache 시간
        window.dnslookup = ntime.domainLookupEnd - ntime.domainLookupStart; //DNS Lookup 시간
        window.connect = ntime.connectEnd - ntime.connectStart; // 웹서버 연결 시간
        window.request = ntime.responseStart - ntime.requestStart; // 요청 소요 시간
        window.response = ntime.responseEnd - ntime.responseStart; // 응답 데이터를 모두 받은 시간
        window.dom = ntime.domComplete - ntime.domLoading; // DOM객체 생성 시간 *******************
        window.load = ntime.loadEventEnd - ntime.loadEventStart; // 브라우저의 Load 이벤트 실행시간
        window.pageEnd = ntime.loadEventEnd - ntime.responseEnd; //  서버에서 페이지를 받고 페이지를 로드하는데 걸린 시간
        window.networkDelay = ntime.responseEnd - ntime.fetchStart; //  네트워크 지연 시간
        console.log("total : " + total + "ms  >>>>>>>  전체 소요시간");
        console.log("redirect : " + redirect + "ms  >>>>>>>   동일 origin에서의 redirect 시간");
        console.log("cache : " + cache + "ms   >>>>>>>  cache 시간");
        console.log("dnslookup : " + dnslookup + "ms  >>>>>>>  DNS Lookup 시간");
        console.log("connect : " + connect + "ms  >>>>>>>  웹서버 연결 시간");
        console.log("request : " + request + "ms  >>>>>>>  요청 소요 시간");
        console.log("response : " + response + "ms  >>>>>>>  첫 응답으로 부터 응답 데이터를 모두 받은 시간");
        console.log("dom : " + dom + "ms  >>>>>>>  DOM객체 로드 완료 시간");
        console.log("load : " + load + "ms  >>>>>>>  브라우저의 Load 이벤트 실행시간");
        console.log("pageEnd : " + pageEnd + "ms  >>>>>>>  서버에서 페이지를 받고 페이지를 로드하는데 걸린 시간");
    }, 30000); //30초 뒤 수행
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
